import json
p='history/transcripts/283326c9-5b0d-5733-99e1-670739471e16/subagents/agent-ad9ef4b9d2e0acf1e.jsonl'
rows=[json.loads(l) for l in open(p)]
for r in rows[-40:]:
    m=r.get('message',{})
    c=m.get('content')
    if isinstance(c,str):
        print(r.get('type'),'TEXT:',c[:600]);continue
    for b in c or []:
        t=b.get('type')
        if t=='text': print(r.get('type'),'TEXT:',b['text'][:800])
        elif t=='tool_use': print(r.get('type'),'TOOL:',json.dumps(b.get('input'))[:900])
        elif t=='tool_result':
            cc=b.get('content')
            if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
            print(r.get('type'),'RESULT:',str(cc)[:1200])
    print('--')
EOF

